import type { Env } from './types';

export type AdmissionRecord = { id: string; email: string; status: 'pending' | 'approved' | 'denied'; epoch: number; createdAt: string };
export type AdmissionState = { records: AdmissionRecord[]; nonces?: Record<string, { owner: string; id: string; status: string; expires: number }>; hour?: string; hourCount?: number; day?: string; dayCount?: number };
export type AdmissionOperation = 'signup' | 'status' | 'list' | 'nonce' | 'decision' | 'dcr';
export const normalizeEmail = (email: string): string => email.trim().toLowerCase();

/** Pure transition, executed inside one DO storage transaction. Never starts a Container. */
export function admissionTransition(state: AdmissionState, op: AdmissionOperation, input: Record<string, string>, now = Date.now()): unknown {
  const email = normalizeEmail(input.email ?? '');
  if (op === 'dcr') {
    const day = new Date(now).toISOString().slice(0, 10), hour = new Date(now).toISOString().slice(0, 13);
    if (state.day !== day) { state.day = day; state.dayCount = 0; }
    if (state.hour !== hour) { state.hour = hour; state.hourCount = 0; }
    if ((state.dayCount ?? 0) >= 1000 || (state.hourCount ?? 0) >= 60) return false;
    state.dayCount = (state.dayCount ?? 0) + 1; state.hourCount = (state.hourCount ?? 0) + 1;
    return true;
  }
  if (op === 'list') return state.records;
  if (op === 'nonce') {
    state.nonces = {}; const tokens: Record<string, string> = {};
    for (const record of state.records) for (const status of ['approved', 'denied']) {
      const value = crypto.randomUUID(); state.nonces[value] = { owner: email, id: record.id, status, expires: now + 600_000 }; tokens[`${record.id}:${status}`] = value;
    }
    return input.id ? tokens[`${input.id}:${input.status}`] ?? '' : tokens;
  }
  if (op === 'decision') {
    const nonce = state.nonces?.[input.nonce]; if (state.nonces) delete state.nonces[input.nonce];
    if (!nonce || nonce.owner !== email || nonce.id !== input.id || nonce.status !== input.status || nonce.expires <= now) return false;
    const record = state.records.find(r => r.id === input.id);
    if (!record || !['approved', 'denied'].includes(input.status)) return false;
    if (record.status !== input.status) { record.epoch++; record.status = input.status as 'approved' | 'denied'; }
    return true;
  }
  const existing = state.records.find(r => r.email === email);
  if (op === 'status' || existing) return existing ?? null;
  if (!email || email.length > 254 || !email.includes('@')) return null;
  if (state.records.length >= 100) return null;
  const record: AdmissionRecord = { id: crypto.randomUUID(), email, status: 'pending', epoch: 0, createdAt: new Date(now).toISOString() };
  state.records.push(record); return record;
}

interface AdmissionRpc { admission(op: AdmissionOperation, input: Record<string, string>): Promise<unknown>; reserveValidationRequest(): Promise<boolean> }
export function admissionStub(env: Env): AdmissionRpc {
  return env.BEE_BRIDGE.get(env.BEE_BRIDGE.idFromName('cf-singleton-container')) as unknown as AdmissionRpc;
}
export async function admissionRecord(env: Env, email: string, create = false): Promise<AdmissionRecord | null> {
  return await admissionStub(env).admission(create ? 'signup' : 'status', { email }) as AdmissionRecord | null;
}
export async function admissionAllowed(env: Env, email: string, epoch?: number): Promise<boolean> {
  try { const r = await admissionRecord(env, email); return r?.status === 'approved' && (epoch === undefined || r.epoch === epoch); }
  catch { return false; }
}
export async function runtimeAllowed(env: Env): Promise<boolean> {
  if (env.SIGNUP_ENABLED !== 'true') return true;
  try { return await admissionStub(env).reserveValidationRequest(); } catch { return false; }
}
export function runtimePaused(): Response {
  return new Response(JSON.stringify({ error: 'temporarily_unavailable', error_description: 'The bounded staging Bee test window is paused. Signup and approval remain available.' }), { status: 503, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
}

import { verifyAccessJwt } from './access';
import { admissionRecord, admissionStub, normalizeEmail, type AdmissionRecord } from './admission';
import { signConsent, verifyConsent } from './state';
import type { Env } from './types';

export const escapeHtml = (s: string): string => s.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#39;');
export function privatePage(body: string, status = 200): Response {
  return new Response(`<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bee staging</title><main>${body}</main>`, { status, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', 'Referrer-Policy': 'no-referrer', 'X-Robots-Tag': 'noindex, nofollow, noarchive', 'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'" } });
}
export async function boundedBody(request: Request, limit = 16_384): Promise<string | null> {
  if (!request.body) return '';
  const reader = request.body.getReader(); const parts: Uint8Array[] = []; let size = 0;
  while (true) { const chunk = await reader.read(); if (chunk.done) break; size += chunk.value.length; if (size > limit) { await reader.cancel(); return null; } parts.push(chunk.value); }
  const bytes = new Uint8Array(size); let offset = 0; for (const part of parts) { bytes.set(part, offset); offset += part.length; }
  return new TextDecoder().decode(bytes);
}
export async function ownerIdentity(request: Request, env: Env): Promise<{ email: string } | null> {
  if (!env.STAGING_PREVIEW_AUD || !env.STAGING_OWNER_EMAIL) return null;
  const identity = await verifyAccessJwt(request, { ...env, ACCESS_AUD: env.STAGING_PREVIEW_AUD });
  return identity && normalizeEmail(identity.email) === normalizeEmail(env.STAGING_OWNER_EMAIL) ? identity : null;
}
export async function pendingPage(env: Env, email: string, request?: Request): Promise<Response> {
  const record = await admissionRecord(env, email, true);
  if (!record) return privatePage('<h1>Request capacity reached</h1><p>Please try later.</p>', 429);
  let retry = '';
  if (request) {
    const url = new URL(request.url);
    const token = await signConsent({ login: normalizeEmail(email), returnPath: '/authorize/email' + url.search }, env.CONSENT_SIGNING_SECRET);
    retry = `<p><a href="/signup/retry?s=${encodeURIComponent(token)}">Check approval and continue</a></p>`;
  }
  return privatePage(`<h1>${record.status === 'denied' ? 'Access not approved' : 'Approval pending'}</h1><p>Your email is verified. Bee connection and data access remain unavailable until the owner approves your request.</p>${retry}<p><a href="/signup">View signup status</a></p>`, record.status === 'denied' ? 403 : 202);
}
export async function signupHandler(request: Request, env: Env): Promise<Response | null> {
  const url = new URL(request.url);
  if (url.pathname === '/') return privatePage('<h1>Bee staging</h1><p>Verify your email to request access. The owner approves requests before Bee connection or data access.</p><p><a href="/signup">Request access</a></p>');
  if (url.pathname.startsWith('/admin')) {
    const owner = await ownerIdentity(request, env);
    if (!owner) return privatePage('<h1>Owner access required</h1>', 403);
    const stub = admissionStub(env);
    if (url.pathname === '/admin/decision' && request.method === 'POST') {
      if (request.headers.get('Origin') !== url.origin || !request.headers.get('Content-Type')?.startsWith('application/x-www-form-urlencoded')) return privatePage('Invalid request', 403);
      const body = await boundedBody(request); if (body === null) return privatePage('Request too large', 413);
      const form = new URLSearchParams(body);
      const accepted = await stub.admission('decision', { email: owner.email, id: form.get('id') ?? '', status: form.get('status') ?? '', nonce: form.get('nonce') ?? '' });
      return accepted ? new Response(null, { status: 303, headers: { Location: '/admin', 'Cache-Control': 'no-store' } }) : privatePage('Invalid or expired action. Reload the request list.', 409);
    }
    if (url.pathname !== '/admin' || request.method !== 'GET') return privatePage('Not found', 404);
    const records = await stub.admission('list', {}) as AdmissionRecord[];
    const nonces = await stub.admission('nonce', { email: owner.email }) as Record<string, string>;
    return privatePage(`<h1>Access requests</h1><p>Approval enables a Bee connection during the bounded test window. Denial immediately blocks subsequent token exchanges and data requests; it does not claim to revoke an upstream Bee credential.</p>${records.map(r => `<section><p>${escapeHtml(r.email)} — ${r.status}</p>${['approved', 'denied'].map(status => `<form method="POST" action="/admin/decision"><input type="hidden" name="id" value="${r.id}"><input type="hidden" name="nonce" value="${nonces[`${r.id}:${status}`]}"><input type="hidden" name="status" value="${status}"><button>${status === 'approved' ? 'Approve' : 'Deny'}</button></form>`).join('')}</section>`).join('') || '<p>No requests.</p>'}`);
  }
  if (url.pathname === '/signup/retry') {
    const identity = await verifyAccessJwt(request, env); if (!identity) return privatePage('Email verification required', 403);
    const state = await verifyConsent<{ login: string; returnPath: string }>(url.searchParams.get('s') ?? '', env.CONSENT_SIGNING_SECRET);
    if (!state || state.login !== normalizeEmail(identity.email) || !state.returnPath.startsWith('/authorize/email?')) return privatePage('Connection request expired. Restart from your MCP client.', 400);
    return new Response(null, { status: 303, headers: { Location: state.returnPath, 'Cache-Control': 'no-store' } });
  }
  if (url.pathname === '/signup') {
    if (request.method !== 'GET') return privatePage('Method not allowed', 405);
    const identity = await verifyAccessJwt(request, env); if (!identity) return privatePage('Email verification required', 403);
    const record = await admissionRecord(env, identity.email, true); if (!record) return privatePage('Request capacity reached', 429);
    return privatePage(`<h1>${record.status === 'approved' ? 'Access approved' : record.status === 'denied' ? 'Access not approved' : 'Approval pending'}</h1><p>${record.status === 'approved' ? 'Add the staging MCP URL in your client to connect your own Bee. Live Bee operations pause when the bounded test window expires.' : 'Your email is verified. The owner must approve your request before Bee connection or data access.'}</p>${record.status === 'approved' ? `<p><label>MCP URL <input readonly value="${escapeHtml(url.origin + '/mcp')}"></label></p>` : ''}<p><a href="/preview/">View homepage and connection instructions</a></p><p><a href="/admin">Manage requests (owner only)</a></p>`);
  }
  return null;
}

