           expiresAt = Date.parse(d.expiresAt) || (Date.now() + 5 * 60 * 1000);
           boxEl.innerHTML = d.qrSvg;
           if (linkEl) linkEl.innerHTML = 'On this phone already? <a href="' + d.connectUrl + '" target="_blank" rel="noopener">Open in the Bee app</a>, approve, then come back to this tab.';
           if (approveBtn) { approveBtn.href = d.connectUrl; approveBtn.style.display = ''; }
           if (connectUrlText && connectUrlPane) { connectUrlText.value = d.connectUrl; connectUrlPane.style.display = ''; }
           statusEl.textContent = isMobile
             ? 'Tap "Open in the Bee app" above to approve — this page finishes by itself.'
             : 'Scan with your phone camera and approve in the Bee app — this page finishes by itself.';
           schedule(myGen);
         }).catch(function () { if (myGen !== gen) return; retryLink('Could not reach the relay.'); });
       }
       function schedule(myGen) {
         if (done || myGen !== gen) return;
         if (Date.now() >= expiresAt) { retryLink('That code expired.'); return; }
        attempt++;
        // Steady 3s early, then doubling, capped at the CLI's 30s MAX_BACKOFF.
        var delay = Math.min(3000 * Math.pow(2, Math.max(0, attempt - 4)), 30000);
        timer = setTimeout(function () { poll(myGen); }, delay);
      }
      function poll(myGen) {
        // Guard against overlapping in-flight polls so two responses can't both
        // observe 'completed' and race a duplicate finish, and drop polls left
        // over from a superseded generation.
        if (done || polling || myGen !== gen) return;
        polling = true;
        post('/pairing/status', { s: s, p: p }).then(function (d) {
          polling = false;
          // 'completed' means the server already ran completeAuthorization and
          // consumed this single-use request, so honor the redirect even if a
          // newer generation (a fresh "Get a new code") superseded this poll —
          // otherwise the OAuth redirect the MCP client is waiting for is lost.
          // Only done (a completion path already took over) suppresses it.
          if (d.status === 'completed') {
             if (done) return;
             if (!d.redirectTo) { retryLink(d.message || 'Pairing finished but no sign-in link was returned.'); return; }
             done = true;
             statusEl.textContent = 'Paired! Finishing sign-in…';
             var f = document.querySelector('form[action="/consent"]');
             if (f) { f.querySelector('button').disabled = true; f.querySelector('input[name="bee_token"]').disabled = true; }
             location.assign(d.redirectTo);
             return;
           }
           if (done || myGen !== gen) return;
           if (d.status === 'expired') { retryLink('That code expired.'); return; }
           if (d.status === 'pending') { schedule(myGen); return; }
          retryLink(d.message || 'Pairing failed.');
        }).catch(function () { polling = false; if (myGen !== gen) return; schedule(myGen); }); // transient network blip: keep polling inside the expiry window
       }
       var pasteForm = document.querySelector('form[action="/consent"]');
       if (pasteForm) pasteForm.addEventListener('submit', function () {
         // The paste path is taking over this single-use authorization request:
         // stop QR polling and bump the generation so no in-flight or scheduled
         // poll can also reach completeAuthorization. Mirrors how a completed QR
         // disables this form — the two completion paths never run concurrently.
         done = true; gen++;
         if (timer) { clearTimeout(timer); timer = null; }
       });
       start();
     })();
     </script>`,
    error ? 400 : 200
  );
}

/** Comma-separated allow-list; self-host denies by default until configured. */
function isAllowed(login: string, env: Env): boolean {
  const list = (env.ALLOWED_GITHUB_LOGIN ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  return list.includes(login.toLowerCase());
}

/** Comma-separated email allow-list for the Cloudflare Access door; lives
 *  beside isAllowed, never replacing it. Denies by default until configured. */
export function isAllowedEmail(email: string, env: Env): boolean {
  const list = (env.ALLOWED_EMAILS ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  return list.includes(email.toLowerCase());
}

/** Defense-in-depth re-check covering BOTH identity namespaces: emails contain
 *  `@` (Access door), GitHub logins cannot (GitHub door) — disjoint by
 *  construction, so one signed `login` field routes to exactly one list. */
async function isAllowedIdentity(login: string, env: Env, epoch?: number): Promise<boolean> {
  if (env.SIGNUP_ENABLED === 'true') return login.includes('@') && Number.isInteger(epoch) && admissionAllowed(env, login, epoch);
  return login.includes("@") ? isAllowedEmail(login, env) : isAllowed(login, env);
}

/** Best-effort delete of one owned broker dir. Wrong identity or a stale blob
 *  is a no-op — never clear a sibling. */
async function clearOwnedBrokerDir(
  broker: BeeBroker,
  blob: unknown,
  secret: string,
  login: string,
  clientId: string
): Promise<void> {
  const id = ownedBrokerId(await unsealBrokerState(str(blob), secret), login, clientId);
  if (!id) return;
  try {
    await broker.clearBeeBroker(id);
  } catch {
    /* leftover dir dies with container sleep */
  }
}

interface ConsentState {
  req: AuthRequest;
  login: string;
  admissionEpoch?: number;
}

export const BeeAuthHandler = {
  async fetch(request: Request, env: Env, _ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/healthz") return new Response("ok", { status: 200 });

    // Commit SHA baked into this immutable version's bundle at build time
    // (scripts/gen-version.mjs). A versions-upload is not a reachable preview
    // URL for this Durable Object + Container Worker; /version still names
    // the bundle. Per-version by construction — no shared/mutable deploy var.
    if (url.pathname === "/version") return new Response(COMMIT_SHA, { status: 200 });

    // ---- MCP client begins authorization ----
    if (["/authorize", "/authorize/email", "/authorize/github"].includes(url.pathname)) {
      let oauthReqInfo: AuthRequest;
      try {
        oauthReqInfo = await env.OAUTH_PROVIDER.parseAuthRequest(request);
      } catch (err) {
        return html(
          `<h2>Invalid authorization request</h2><p>${
            err instanceof Error ? err.message : "Malformed request."
          }</p><p>MCP clients should register via <code>/register</code> and retry.</p>`,
          400
        );
      }
      if (!(await env.OAUTH_PROVIDER.lookupClient(oauthReqInfo.clientId))) {
        return html(`<h2>Unknown client</h2><p>Register via <code>/register</code> first.</p>`, 400);
      }
      // Only the email route is protected at the Access edge. The chooser and
      // direct GitHub route must remain reachable without an Access session.
      if (url.pathname === "/authorize" && env.ACCESS_TEAM_DOMAIN && env.ACCESS_AUD) {
        const query = url.search.replaceAll("&", "&amp;").replaceAll('"', "&quot;")
          .replaceAll("<", "&lt;").replaceAll(">", "&gt;");
        return html(`<h2>Connect your Bee</h2><p>Choose how to sign in.</p>
          <a class="btn-hero" href="/authorize/email${query}">Continue with email</a>
          <p><a href="/authorize/github${query}">Continue with GitHub</a></p>`);
      }
      if (url.pathname === "/authorize/email") {
        const access = await verifyAccessJwt(request, env);
        if (!access) {
          return html(`<h2>Email sign-in could not be verified</h2><p>Restart the connection from your client. If this continues, contact the relay operator.</p>`, 403);
        }
        if (env.SIGNUP_ENABLED === 'true' && !(await admissionAllowed(env, access.email))) return pendingPage(env, access.email, request);
        if (env.SIGNUP_ENABLED !== 'true' && !isAllowedEmail(access.email, env)) {
          return html(
            `<h2>Not authorized</h2><p>Signed in as <b>${access.email}</b>, but this self-host instance only allows its configured operator(s). Set <code>ALLOWED_EMAILS</code> and retry.</p>`,
            403
          );
        }
        const signed = await signConsent(
          { req: oauthReqInfo, login: access.email, ...(env.SIGNUP_ENABLED === 'true' ? { admissionEpoch: (await admissionRecord(env, access.email))?.epoch } : {}) } satisfies ConsentState,
          env.CONSENT_SIGNING_SECRET
        );
        return consentForm(access.email, signed, isMobileUA(request));
      }

      const gh = new URL("https://github.com/login/oauth/authorize");
      gh.searchParams.set("client_id", env.GITHUB_CLIENT_ID);
      gh.searchParams.set("redirect_uri", `${url.origin}/callback`);
      gh.searchParams.set("state", encodeState(oauthReqInfo));
      return Response.redirect(gh.toString(), 302);
    }

    // ---- GitHub returns with identity ----
    if (url.pathname === "/callback") {
      const code = url.searchParams.get("code");
      const state = url.searchParams.get("state");
      if (!code || !state) return html(`<h2>Missing code or state.</h2>`, 400);
      const oauthReqInfo = decodeState<AuthRequest>(state);

      // Exchange for a transient user token (used once, then discarded).
      const tokenRes = await fetch("https://github.com/login/oauth/access_token", {
        method: "POST",
        headers: { accept: "application/json", "content-type": "application/json", "user-agent": UA },
        body: JSON.stringify({
          client_id: env.GITHUB_CLIENT_ID,
          client_secret: env.GITHUB_CLIENT_SECRET,
          code,
          redirect_uri: `${url.origin}/callback`,
        }),
      });
      const tokenJson = (await tokenRes.json()) as { access_token?: string; error?: string };
      if (!tokenJson.access_token) {
        return html(`<h2>GitHub login failed.</h2><p>${tokenJson.error ?? "no token returned"}</p>`, 400);
      }

      const userRes = await fetch(`${GH}/user`, {
        headers: {
          authorization: `Bearer ${tokenJson.access_token}`,
          accept: "application/vnd.github+json",
          "user-agent": UA,
        },
      });
      if (!userRes.ok) return html(`<h2>Could not read GitHub identity.</h2>`, 400);
      const user = (await userRes.json()) as { login: string };

      if (!isAllowed(user.login, env)) {
        return html(
          `<h2>Not authorized</h2><p>Signed in as <b>${user.login}</b>, but this self-host instance only allows its configured operator(s). Set <code>ALLOWED_GITHUB_LOGIN</code> and reconnect.</p>`,
          403
        );
      }

      // Identity proven + allow-listed. Carry it (signed) to the consent step;
      // the GitHub token is now discarded. No Bee token exists yet.
      const signed = await signConsent(
        { req: oauthReqInfo, login: user.login } satisfies ConsentState,
        env.CONSENT_SIGNING_SECRET
      );
      return consentForm(user.login, signed, isMobileUA(request));
    }

    // ---- Bee-token consent (capture into encrypted props) ----
    if (url.pathname === "/consent" && request.method === "POST") {
      const form = await request.formData();
      const signed = String(form.get("s") ?? "");
      const beeToken = String(form.get("bee_token") ?? "").trim();

      const cs = await verifyConsent<ConsentState>(signed, env.CONSENT_SIGNING_SECRET);
      if (!cs || !cs.login || !cs.req) {
        return html(`<h2>Consent state invalid or tampered.</h2><p>Restart the connection from your client.</p>`, 400);
      }

      // Defense in depth: re-check the allow-list against the signed login —
      // both namespaces (GitHub login or Access email; disjoint by `@`).
      if (!(await isAllowedIdentity(cs.login, env, cs.admissionEpoch))) {
        return html(`<h2>Not authorized</h2><p><b>${cs.login}</b> is not on this instance's allow-list.</p>`, 403);
      }

      if (!beeToken) {
        return consentForm(cs.login, signed, isMobileUA(request), "Please paste your Bee API token.");
      }

      // Validate the token before binding it — a bad token must not become a
      // confusing post-connect failure. This is the first real call through the
      // private-CA bridge container; a transport error here means it isn't ready.
      if (!(await runtimeAllowed(env))) return runtimePaused();
      const stub = getContainer(env.BEE_BRIDGE); // shared singleton; never per-user (E0014)
      const check = await beeGetMe(beeToken, stub);
      if (!check.ok) {
        return consentForm(cs.login, signed, isMobileUA(request), `Bee did not accept that: ${check.message}`);
      }

      // Bind identity + Bee token into the user's encrypted grant props.
      if (!(await isAllowedIdentity(cs.login, env, cs.admissionEpoch))) return json({ error: 'access_denied' }, 403);
      const { redirectTo } = await env.OAUTH_PROVIDER.completeAuthorization({
        request: cs.req,
        userId: cs.login,
        metadata: { label: cs.login },
        scope: ["bee_read"],
        props: { login: cs.login, beeToken, ...(env.SIGNUP_ENABLED === 'true' ? { admissionEpoch: cs.admissionEpoch } : {}) },
      });
      return Response.redirect(redirectTo, 302);
    }

    // ---- Hosted CLI broker start (consent page JS) ----
    if (url.pathname === "/pairing/start" && request.method === "POST") {
      const body = await readJson(request);
      const cs = await verifyConsent<ConsentState>(str(body?.["s"]), env.CONSENT_SIGNING_SECRET);
      if (!cs || !cs.login || !cs.req) {
        return json({ status: "error", message: "Consent state invalid — restart the connection from your client." }, 400);
      }
      if (!(await isAllowedIdentity(cs.login, env, cs.admissionEpoch))) {
        return json({ status: "error", message: "Not authorized." }, 403);
      }

      if (!(await runtimeAllowed(env))) return runtimePaused();
      const broker = getContainer(env.BEE_BRIDGE) as unknown as BeeBroker;
      await clearOwnedBrokerDir(broker, body?.["p"], env.CONSENT_SIGNING_SECRET, cs.login, cs.req.clientId);

      const brokerId = newBrokerId();
      let outcome: Awaited<ReturnType<BeeBroker["startBeeBroker"]>>;
      try {
        outcome = await broker.startBeeBroker(brokerId);
      } catch {
        return json({ status: "error", message: "hosted Bee CLI broker unreachable" }, 502);
      }
      if (outcome.status !== "pending") {
        const message = outcome.status === "error" ? outcome.message : "Pairing request failed — try again.";
        return json({ status: "error", message }, 502);
      }

      const sealed = await sealBrokerState(
        {
          kind: "cli-broker-v1",
          brokerId,
          login: cs.login,
          clientId: cs.req.clientId,
          iat: Date.now(),
        },
        env.CONSENT_SIGNING_SECRET
      );
      return json({
        status: "pending",
        expiresAt: outcome.expiresAt,
        connectUrl: outcome.connectUrl,
        qrSvg: renderSVG(outcome.connectUrl, { border: 2 }),
        p: sealed,
      });
    }

    // ---- Hosted CLI broker poll ----
    if (url.pathname === "/pairing/status" && request.method === "POST") {
      const body = await readJson(request);
      const cs = await verifyConsent<ConsentState>(str(body?.["s"]), env.CONSENT_SIGNING_SECRET);
      if (!cs || !cs.login || !cs.req) {
        return json({ status: "error", message: "Consent state invalid — restart the connection from your client." }, 400);
      }
      if (!(await isAllowedIdentity(cs.login, env, cs.admissionEpoch))) {
        return json({ status: "error", message: "Not authorized." }, 403);
      }
      const st = await unsealBrokerState(str(body?.["p"]), env.CONSENT_SIGNING_SECRET);
      if (!st || st.login !== cs.login || st.clientId !== cs.req.clientId) {
        return json({ status: "error", message: "Pairing state invalid or stale — get a new code." }, 400);
      }

      if (!(await runtimeAllowed(env))) return runtimePaused();
      const broker = getContainer(env.BEE_BRIDGE) as unknown as BeeBroker;
      let outcome: Awaited<ReturnType<BeeBroker["resumeBeeBroker"]>>;
      try {
        outcome = await broker.resumeBeeBroker(st.brokerId);
      } catch {
        return json({ status: "error", message: "hosted Bee CLI broker unreachable" }, 502);
      }
      if (outcome.status === "pending") return json({ status: "pending" });
      if (outcome.status === "expired") {
        await clearOwnedBrokerDir(broker, body?.["p"], env.CONSENT_SIGNING_SECRET, cs.login, cs.req.clientId);
        return json({ status: "expired" });
      }
      if (outcome.status === "error") return json({ status: "error", message: outcome.message }, 502);

      const beeToken = outcome.token;
      const stub = getContainer(env.BEE_BRIDGE);
      const check = await beeGetMe(beeToken, stub);
      if (!check.ok) {
        try {
          await broker.clearBeeBroker(st.brokerId);
        } catch {
          /* best-effort */
        }
        return json({ status: "error", message: `Bee did not accept the paired token: ${check.message}` }, 400);
      }

      if (!(await isAllowedIdentity(cs.login, env, cs.admissionEpoch))) {
        try { await broker.clearBeeBroker(st.brokerId); } catch { /* Do not claim cleanup on failure. */ }
        return json({ error: 'access_denied' }, 403);
      }
      const { redirectTo } = await env.OAUTH_PROVIDER.completeAuthorization({
        request: cs.req,
        userId: cs.login,
        metadata: { label: cs.login },
        scope: ["bee_read"],
        props: { login: cs.login, beeToken, ...(env.SIGNUP_ENABLED === 'true' ? { admissionEpoch: cs.admissionEpoch } : {}) },
      });
      try {
        await broker.clearBeeBroker(st.brokerId);
      } catch {
        /* best-effort — grant is already bound; leftover dir dies with container sleep */
      }
      return json({ status: "completed", redirectTo });
    }

    return new Response("Not found", { status: 404 });
  },
};

/**
 * The gated /mcp API. OAuthProvider has verified the access token and decrypted
 * THIS grant's props into ctx.props before we run. v0.3 per-grant custody: props
 * carry identity (login) AND the user's Bee bearer (beeToken). The bearer is
 * read from the decrypted grant per request — never from env, never logged,
 * never returned.
 *
 * Tools: `whoami` (Phase 1, Bee GET /v1/me — the live-credential smoke check)
 * plus the Phase-2 read surface — `bee_docs` (serves the Bee-API-usage reference)
 * and `bee_read` (GET any /v1/* path, or POST to the allow-listed /v1/search/*;
 * read-only by construction). `bee_write` remains deferred to the write phase.
 */

import { createMcpHandler } from "agents/mcp";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { getContainer } from "@cloudflare/containers";
import { z } from "zod";
import { beeGetMe, beeRead } from "./bee";
import { BEE_API_USAGE_DOC } from "./bee-api-usage-doc";
import { classifyPath, deriveTenantKey, statusClassOf, withTelemetry } from "./telemetry";
import type { Env, GrantProps } from "./types";
import { admissionAllowed, runtimeAllowed, runtimePaused } from './admission';

function buildServer(env: Env, props: GrantProps, tenantKey: string): McpServer {
  const server = new McpServer({ name: "bee-ai-auth-mcp", version: "0.1.0" });

  server.registerTool(
    "whoami",
    {
      title: "Confirm the Bee credential",
      annotations: {
        title: "Confirm the Bee credential",
        readOnlyHint: true,
        idempotentHint: true,
        openWorldHint: true,
      },
      description:
        "Confirm this relay can reach Bee with your captured credential. Calls Bee GET /v1/me " +
        "and returns the account identity (read-only). This is the Phase-1 wire check: if it " +
        "succeeds over the connector on your phone, the all-surface path works. Your Bee token " +
        "is read from your encrypted grant and is never returned.",
      inputSchema: {},
    },
    withTelemetry(env, tenantKey, "whoami", (tele) => async () => {
      // One shared, token-agnostic bridge: getContainer with no name resolves the
      // singleton ("cf-singleton-container"). Do NOT pass a per-user name — that
      // would shard the deliberately single shared bridge (multitenancy rule, E0014).
      const stub = getContainer(env.BEE_BRIDGE);
      const result = await beeGetMe(props.beeToken, stub);
      // bridge_ms/bridge_state come from the bridge.fetch leg measured inside
      // bee.ts — not the whole call (which includes the body read). bridgeCold is
      // set for non-2xx too: a cold container can still return 401/403/5xx.
      tele.bridgeMs = result.bridgeMs;
      tele.statusClass = statusClassOf(result.ok ? 200 : result.status);
      tele.bridgeCold = result.bridgeCold;
      if (!result.ok) {
        const wall = {
          error: "bee_unreachable_or_rejected",
          status: result.status,
          detail: result.message,
        };
        return { content: [{ type: "text" as const, text: JSON.stringify(wall, null, 2) }], isError: true };
      }
      const payload = {
        connected_as: props.login, // who authenticated to the relay
        bee: result.account, // the Bee account /v1/me returned
      };
      return { content: [{ type: "text" as const, text: JSON.stringify(payload, null, 2) }] };
    })
  );

  server.registerTool(
    "bee_docs",
    {
      title: "Bee API usage reference",
      annotations: {
        title: "Bee API usage reference",
        readOnlyHint: true,
        idempotentHint: true,
        openWorldHint: false,
      },
      description:
        "Return the Bee API usage reference: which /v1/* read endpoints exist, how to shape paths and the search body, pagination/cursors, and what is excluded. Read this before calling bee_read.",
      inputSchema: {},
    },
    withTelemetry(env, tenantKey, "bee_docs", (tele) => async () => {
      tele.statusClass = "2xx"; // local doc, no network leg
      return {
        content: [{ type: "text" as const, text: BEE_API_USAGE_DOC }],
      };
    })
  );

  server.registerTool(
    "bee_read",
    {
      title: "Read from the Bee API",
      annotations: {
        title: "Read from the Bee API",
        readOnlyHint: true,
        idempotentHint: true,
        openWorldHint: true,
      },
      description:
        "Read from the Bee API through the relay (your Bee token is read from your encrypted grant — never shown). Give a `path` beginning with /v1/. A GET is issued for every path EXCEPT the /v1/search/* endpoints, which are POSTed with the `search` body. Read-only by construction: it never issues a mutating verb. See bee_docs for the endpoint list.",
      inputSchema: {
        path: z
          .string()
          .describe(
            "Bee API path beginning with /v1/ (e.g. /v1/conversations, /v1/conversations/:id, /v1/changes?cursor=..., /v1/search/conversations)."
          ),
        search: z
          .record(z.string(), z.unknown())
          .optional()
          .describe(
            "JSON body for the /v1/search/* endpoints only (e.g. { query, limit, cursor }); ignored for GET paths."
          ),
      },
    },
    withTelemetry(env, tenantKey, "bee_read", (tele) => async ({ path, search }: { path: string; search?: Record<string, unknown> }) => {
      tele.pathClass = classifyPath(path);
      const stub = getContainer(env.BEE_BRIDGE);
      const result = await beeRead(props.beeToken, stub, path, search);
      // bridge_ms/bridge_state come from the bridge.fetch leg measured inside
      // bee.ts — not the whole call (which includes the body read). bridgeCold is
      // set for non-2xx too: a cold container can still return 401/403/5xx.
      tele.bridgeMs = result.bridgeMs;
      tele.statusClass = statusClassOf(result.status);
      tele.bridgeCold = result.bridgeCold;
      if (!result.ok) {
        const wall = { error: "bee_read_failed", status: result.status, detail: result.message };
        return { content: [{ type: "text" as const, text: JSON.stringify(wall, null, 2) }], isError: true };
      }
      const payload = { status: result.status, truncated: result.truncated ?? false, body: result.body };
      return { content: [{ type: "text" as const, text: JSON.stringify(payload, null, 2) }] };
    })
  );

  return server;
}

export const McpApiHandler = {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const props = (ctx as ExecutionContext & { props?: GrantProps }).props;
    if (!props?.login) {
      return new Response("Grant is not bound to an identity. Disconnect and reconnect.", { status: 403 });
    }
    if (env.SIGNUP_ENABLED === 'true' && (!Number.isInteger(props.admissionEpoch) || !(await admissionAllowed(env, props.login, props.admissionEpoch)))) return new Response('Access not approved. Reconnect after owner approval.', { status: 403, headers: { 'Cache-Control': 'no-store' } });
    if (!props.beeToken) {
      // A grant from before the custody bend (login only). Force a reconnect so
      // the consent step can capture a Bee token into the encrypted props.
      return new Response(
        "Grant has no Bee credential. Disconnect and reconnect to supply your Bee token at consent.",
        { status: 403 }
      );
    }
    if (!(await runtimeAllowed(env))) return runtimePaused();
    const tenantKey = await deriveTenantKey(env, props.login);
    const handler = createMcpHandler(buildServer(env, props, tenantKey), { route: "/mcp" });
    return handler(request, env, ctx);
  },
};

