// Deterministic local build only. No deploy, network call, or secret input.
const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');
const crypto = require('node:crypto');
const base = path.join(__dirname, 'bee-source-recovery/embedded-runtime');
const esbuild = require(path.join(base, 'node_modules/esbuild'));
(async () => {
  const result = await esbuild.build({ absWorkingDir: base, entryPoints: ['src/staging.ts'], bundle: true, format: 'esm', platform: 'neutral', target: 'es2022', conditions: ['workerd', 'worker', 'browser'], mainFields: ['module', 'main'], external: ['cloudflare:*', 'node:*'], write: false, metafile: true, legalComments: 'none', plugins: [{ name: 'node-path-static-import', setup(build) { build.onResolve({ filter: /^path$/ }, () => ({ path: 'path', namespace: 'builtin-shim' })); build.onLoad({ filter: /.*/, namespace: 'builtin-shim' }, () => ({ contents: "export * from 'node:path'; import path from 'node:path'; export default path;", loader: 'js' })); } }] });
  const module = result.outputFiles[0].contents;
  fs.writeFileSync(path.join(__dirname, 'signup-module.js'), module);
  const archive = zlib.gzipSync(module).toString('base64') + '\n';
  fs.writeFileSync(path.join(__dirname, 'signup-module.gz.base64'), archive);
  const receipt = { sha256: crypto.createHash('sha256').update(module).digest('hex'), bytes: module.length, archive_bytes: Buffer.byteLength(archive), inputs: Object.keys(result.metafile.inputs), status: 'local-built-not-deployed' };
  fs.writeFileSync(path.join(__dirname, 'signup-build-receipt.json'), JSON.stringify(receipt, null, 2) + '\n');
  console.log(JSON.stringify({ ...receipt, inputs: receipt.inputs.length }));
})().catch(() => { console.error('Local signup build failed'); process.exitCode = 1; });

