async () => {
  const account = 'b03e6ea242724c05eb97eb732cceb21d';
  const worker = 'bee-validation-20260909';
  const workerId = '9b7d9c86f72e4af38303e3f9e63ee3c9';
  const oldVersion = '75ca2a71-dcf9-4cfd-8307-63dfcfe3f2a9';
  const oldHash = '4a0be14b596068c32a6aab5f188abaa8ebcf4430721bd90af4d89cda7a651eee';
  const newHash = '__REVIEWED_MODULE_SHA256__';
  const moduleGzipBase64 = '__REVIEWED_MODULE_GZIP_BASE64__';
  const ownerApp = '8fc54e03-24c8-4c02-9376-7c639a3ca94e';
  const emailApp = '5ae63959-05d5-45a7-a9bd-237c271245c0';
  const assert = (ok, message) => { if (!ok) throw Error(message); };
  let phase = 'preflight', version = null;
  const plainBindings = bs => JSON.stringify([...bs].map(b => b.type === 'secret_text' ? {type:b.type,name:b.name} : b).sort((a,b)=>a.name.localeCompare(b.name)));
  async function api(method, path, body) {
    const r = await fetch('https://api.cloudflare.com/client/v4/accounts/' + account + path, {method, redirect:'manual', headers:body ? {'Content-Type':'application/json'} : {}, body:body ? JSON.stringify(body) : undefined});
    const j = await r.json();
    assert(r.ok && j.success, 'provider ' + method + ' HTTP ' + r.status);
    return j.result;
  }
  async function hash(bytes) { return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)), x=>x.toString(16).padStart(2,'0')).join(''); }
  const decode = text => Uint8Array.from(atob(text), c=>c.charCodeAt(0));
  async function bounds() {
    const w = await api('GET','/workers/workers/' + workerId);
    const ingress = await api('GET','/workers/scripts/' + worker + '/subdomain');
    assert(w.observability?.enabled === false && w.observability?.logs?.enabled === false && w.observability?.traces?.enabled === false && w.logpush === false, 'logging changed');
    assert(ingress.enabled === true && ingress.previews_enabled === false, 'ingress changed');
    return JSON.stringify({observability:w.observability,logpush:w.logpush,ingress});
  }
  try {
    assert(accountId === account, 'account mismatch');
    assert(/^[a-f0-9]{64}$/.test(newHash) && !moduleGzipBase64.startsWith('__'), 'unbound reviewed module');
    const compressed = decode(moduleGzipBase64);
    const stream = new ReadableStream({start(controller){controller.enqueue(compressed);controller.close();}}).pipeThrough(new DecompressionStream('gzip'));
    const sourceBytes = new Uint8Array(await new Response(stream).arrayBuffer());
    assert(await hash(sourceBytes) === newHash, 'reviewed source mismatch');
    let binary = ''; for (let i=0;i<sourceBytes.length;i+=8192) binary += String.fromCharCode(...sourceBytes.subarray(i,i+8192));
    const beforeBounds = await bounds();
    const production = JSON.stringify(await api('GET','/workers/scripts/bee-ai-auth-mcp/deployments'));
    const apps = await api('GET','/access/apps?per_page=100');
    const appSnapshots = {};
    for (const app of apps) appSnapshots[app.id] = {app:await api('GET','/access/apps/' + app.id), policies:await api('GET','/access/apps/' + app.id + '/policies')};
    const d = await api('GET','/workers/scripts/' + worker + '/deployments');
    assert(d.deployments[0].versions.length === 1 && d.deployments[0].versions[0].version_id === oldVersion, 'active drift');
    const v = await api('GET','/workers/workers/' + workerId + '/versions/' + oldVersion + '?include=modules');
    assert(v.modules.length === 1 && await hash(decode(v.modules[0].content_base64)) === oldHash, 'old source drift');
    assert(v.bindings.every(b=>b.type !== 'secret_text'), 'unexpected prior secrets');
    assert(v.bindings.find(b=>b.name==='BEE_BRIDGE')?.namespace_id === '5b99701b01df4b2b886be69a0202a0e9', 'namespace drift');
    assert(v.bindings.find(b=>b.name==='OAUTH_KV')?.namespace_id === 'd57ff6004e48496893132f343a8f4a81', 'KV drift');
    const ownerPolicies = appSnapshots[ownerApp].policies;
    assert(ownerPolicies.length === 1 && ownerPolicies[0].decision === 'allow' && ownerPolicies[0].include.length === 1, 'owner policy drift');
    // This identity and generated secret never leave trusted execution.
    const ownerEmail = ownerPolicies[0].include[0].email?.email;
    assert(typeof ownerEmail === 'string' && ownerEmail.includes('@'), 'owner identity unavailable');
    const signing = Array.from(crypto.getRandomValues(new Uint8Array(32)), x=>x.toString(16).padStart(2,'0')).join('');
    const body = {};
    for (const k of ['assets','bindings','cache_options','compatibility_date','compatibility_flags','containers','limits','main_module','migration_tag','modules','package_dependencies','placement','usage_model']) if(v[k] !== undefined) body[k]=v[k];
    body.exports = {...(v.exports||{}),BeeBridge:{type:'durable-object',storage:'sqlite',container:'BeeBridge'}};
    body.containers = body.containers.map(c=>c.class_name==='BeeBridge'?{...c,name:'BeeBridge'}:c);
    body.modules = [{...v.modules[0],content_base64:btoa(binary)}];
    const changes = {ACCESS_AUD:appSnapshots[emailApp].app.aud,STAGING_PREVIEW_AUD:appSnapshots[ownerApp].app.aud,SIGNUP_ENABLED:'true'};
    body.bindings = v.bindings.filter(b=>!Object.hasOwn(changes,b.name));
    body.bindings.push(...Object.entries(changes).map(([name,text])=>({type:'plain_text',name,text})), {type:'secret_text',name:'STAGING_OWNER_EMAIL',text:ownerEmail},{type:'secret_text',name:'CONSENT_SIGNING_SECRET',text:signing});
    // Runtime activation is a separate bounded step after source + Access acceptance.
    for (const n of ['VALIDATION_STARTS_AT','VALIDATION_EXPIRES_AT']) assert(body.bindings.find(b=>b.name===n)?.text === '', 'runtime window must remain closed');
    body.annotations = {'workers/message':'Verified-email signup and owner admission; OAuth discovery separated from runtime gate.'};
    phase = 'upload';
    version = (await api('POST','/workers/workers/' + workerId + '/versions?deploy=false',body)).id;
    const uploaded = await api('GET','/workers/workers/' + workerId + '/versions/' + version + '?include=modules');
    assert(uploaded.modules.length === 1 && await hash(decode(uploaded.modules[0].content_base64)) === newHash, 'upload source mismatch');
    assert(plainBindings(uploaded.bindings) === plainBindings(body.bindings), 'upload binding mismatch');
    for (const k of ['assets','cache_options','compatibility_date','compatibility_flags','containers','limits','main_module','migration_tag','package_dependencies','placement','usage_model']) {
      if(body[k] !== undefined) assert(JSON.stringify(uploaded[k]) === JSON.stringify(body[k]), 'preserved version metadata mismatch: ' + k);
    }
    assert((await api('GET','/workers/scripts/' + worker + '/deployments')).deployments[0].versions[0].version_id === oldVersion, 'upload caused deployment');
    phase = 'deploy';
    await api('POST','/workers/scripts/' + worker + '/deployments',{strategy:'percentage',versions:[{version_id:version,percentage:100}],annotations:{'workers/message':'Activate signup/discovery source only; Access policies unchanged; runtime closed.'}});
    phase = 'readback';
    const after = await api('GET','/workers/scripts/' + worker + '/deployments');
    assert(after.deployments[0].versions.length === 1 && after.deployments[0].versions[0].version_id === version && after.deployments[0].versions[0].percentage === 100, 'active mismatch');
    const settings = await api('GET','/workers/scripts/' + worker + '/settings');
    assert(plainBindings(settings.bindings) === plainBindings(body.bindings), 'effective bindings mismatch');
    const namespaces = [];
    let namespaceInventoryComplete = false;
    for(let page=1;page<=10;page++) {
      const rows = await api('GET','/workers/durable_objects/namespaces?page=' + page + '&per_page=20');
      namespaces.push(...rows);
      if(rows.length<20) { namespaceInventoryComplete = true; break; }
    }
    assert(namespaceInventoryComplete, 'namespace inventory truncated');
    const namespace = namespaces.find(n=>n.id==='5b99701b01df4b2b886be69a0202a0e9');
    assert(namespace?.script === worker && namespace.class === 'BeeBridge' && namespace.use_sqlite === true && namespace.use_containers === true, 'Container linkage changed');
    assert(await bounds() === beforeBounds, 'boundaries changed');
    assert(JSON.stringify(await api('GET','/workers/scripts/bee-ai-auth-mcp/deployments')) === production, 'production changed');
    for(const [id,s] of Object.entries(appSnapshots)) {
      assert(JSON.stringify(await api('GET','/access/apps/' + id)) === JSON.stringify(s.app), 'Access app changed');
      assert(JSON.stringify(await api('GET','/access/apps/' + id + '/policies')) === JSON.stringify(s.policies), 'Access policy changed');
    }
    return {accepted:true,observed:new Date().toISOString(),phase,version,deployment:after.deployments[0].id,module_sha256:newHash,module_bytes:sourceBytes.length,owner_identity_copied_from_preserved_policy:true,secrets_created:['STAGING_OWNER_EMAIL','CONSENT_SIGNING_SECRET'],runtime_closed:true,access_unchanged:true,production_unchanged:true,logging_disabled:true};
  } catch(e) {
    return {accepted:false,phase,version,error:e.message};
